import{z as p,x as E,o as l,c as _,q as o,j as i,D as t,d as n,s,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"选择性扫描","description":"","frontmatter":{"title":"选择性扫描","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/selective-scan.md","filePath":"llm/selective-scan.md","lastUpdated":1791063341000}'),A={name:"llm/selective-scan.md"};function d(D,a,h,m,c,C){const r=E("Mermaid");return l(),_("div",null,[a[2]||(a[2]=o('<h1 id="选择性扫描" tabindex="-1">选择性扫描 <a class="header-anchor" href="#选择性扫描" aria-label="Permalink to &quot;选择性扫描&quot;">​</a></h1><div class="epigraph"><p>让 $\\Delta,B,C$ 随当前 token 变化，状态更新就变成内容选择：该记的写入，该忘的滤掉。</p><footer>—— Gu &amp; Dao, Mamba: Linear-Time Sequence Modeling with Selective State Spaces, 2023</footer></div><p><a href="/llm/hippo-s4">上一课</a>的 \\(A,B,C,\\Delta\\) 对所有时间步共享。<a href="/llm/mamba">Mamba</a> 课已经陈述过「要选择」，本课把选择收成可引用的算子：<strong>选择性扫描</strong>——沿长度做依赖于输入的状态更新，而不能再预计算一条卷积核。后课硬件感知扫描解决它怎么在 GPU 上算；本课只钉动力学与为何卷积路断了。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>时不变卷积核 \\(K_k=C\\overline{A}^k\\overline{B}\\) 与 \\(x\\) 无关，能 FFT 或预计算。语言模型需要按内容忽略或记住。若 \\(\\overline{B}_t\\)、\\(\\Delta_t\\) 依赖 \\(x_t\\)，则每步的 \\(\\overline{A}_t\\) 不同，不存在与输入无关的 \\(K\\)，S4 的卷积算法失效。缺口是：在放弃全局卷积之后，仍用一条<strong>沿序列的扫描</strong>计算 \\(h_t=\\overline{A}_t h_{t-1}+\\overline{B}_t x_t\\)，并保持线性时间。</p><p><span class="marginnote">可以想象成一边读小说一边记「心算摘要」：不管小说多长，笔记本只有固定几行，每翻一页都要决定记什么、擦什么。注意力是随时翻回前文任何一页对照，选择性扫描则是只带着这份摘要往前走——这就是「读摘要」与「查原表」的区别。</span></p><p>选择放在 \\(\\Delta\\) 与 \\(B,C\\) 上、保持 \\(A\\) 结构化（常对角），是 Mamba 的具体选择，不是唯一可能。本课以这条为默认，后课 GLA、delta rule 会换更新规则。</p><p><span class="marginnote">扫描是前缀式结合：先左后右累积。它不是注意力分数矩阵。不要把 selective scan 说成「另一种 softmax」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从输入 \\(x_t\\) 投影得到 \\(\\Delta_t,B_t,C_t\\)（以及可选的门）。\\(A\\) 仍是按通道的对角或近对角，离散化</p> \\[\\overline{A}_t=\\exp(\\Delta_t A),\\qquad \\overline{B}_t=\\Delta_t B_t \\]<p>（连续到离散的具体公式以实现为准，课序只保留「\\(\\Delta_t\\) 调制衰减与写入」）。然后</p> \\[h_t=\\overline{A}_t h_{t-1}+\\overline{B}_t x_t,\\qquad y_t=C_t h_t. \\]<p>沿 \\(t=1..n\\) 扫描。因果语言模型与这条方向一致；双向要做两次扫描或改掩码，不是默认。</p><p>因为 \\(\\overline{A}_t\\) 可乘，扫描在代数上是结合的，这才允许后课的分块并行：块内串行、块间利用结合律。本课先承认逐步定义。</p><h3 id="选择做了什么" tabindex="-1">选择做了什么 <a class="header-anchor" href="#选择做了什么" aria-label="Permalink to &quot;选择做了什么&quot;">​</a></h3><p>\\(\\Delta_t\\) 大：当前 \\(x_t\\) 强写入、旧状态快衰减，相当于重置。\\(\\Delta_t\\) 小：跳过当前 token，状态近似拷贝。\\(B_t\\) 决定写进哪些状态维，\\(C_t\\) 决定读出。这与注意力的「对哪些过去位置加权」不同：过去已经被压进 \\(h\\)，读的是摘要不是表。</p>',17)),(l(),i(B,null,{default:t(()=>[s(r,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%96%B0%20token%20x_t%20%E5%88%B0%E6%9D%A5%22%5D%20--%3E%20D%7B%22Delta_t%20%E5%8F%96%E5%A4%9A%E5%A4%A7%EF%BC%9F%22%7D%0A%20%20D%20--%3E%7C%22%E5%A4%A7%22%7C%20W%5B%22%E5%BC%BA%E5%86%99%E5%85%A5%20%2B%20%E6%97%A7%E7%8A%B6%E6%80%81%E5%BF%AB%E8%A1%B0%E5%87%8F%EF%BC%9A%E9%87%8D%E7%BD%AE%22%5D%0A%20%20D%20--%3E%7C%22%E5%B0%8F%22%7C%20S%5B%22%E8%BF%91%E4%BC%BC%E8%B7%B3%E8%BF%87%EF%BC%8C%E7%8A%B6%E6%80%81%E6%8B%B7%E8%B4%9D%E5%89%8D%E8%BF%9B%22%5D%0A%20%20W%20--%3E%20BC%5B%22B%20%E9%80%89%E5%86%99%E5%85%A5%E7%BB%B4%EF%BC%8CC%20%E9%80%89%E8%AF%BB%E5%87%BA%E7%BB%B4%22%5D%0A%20%20S%20--%3E%20BC%0A%20%20BC%20--%3E%20H%5B%22%E5%BE%97%E5%88%B0%E6%9B%B4%E6%96%B0%E5%90%8E%E7%9A%84%E6%91%98%E8%A6%81%20h_t%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p><span class="marginnote">给个数字感受 \\(\\Delta\\)：设 \\(A\\) 的对角为 \\(-1\\)，取 \\(\\Delta=0.01\\) 时 \\(\\exp(\\Delta A)\\approx 0.99\\)，旧状态几乎原样保留；取 \\(\\Delta=5\\) 时 \\(\\exp(-5)\\approx 0.007\\)，旧记忆只剩不到 1%，等于一次重置。模型就是用这个旋钮在「记」与「忘」之间切换。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>固定大小的 \\(h\\in\\mathbb{R}^{N}\\) 是有损压缩。选择决定压缩器的编码表随 token 变，因此对噪声 token 可以近似恒等传递，对关键 token 可以覆盖旧内容。这解释了为何同样 \\(N\\)，选择性 SSM 比 S4 更像语言模型：容量仍小，编码策略变聪明。</p><p>梯度沿扫描反传，是线性 RNN 的反向扫描，数值上依赖 \\(\\overline{A}_t\\) 不要长期大于 1。\\(\\exp(\\Delta A)\\) 在 \\(A\\) 的对角为负时是衰减，这是稳定性来源。把 \\(A\\) 学成正会炸，初始化与参数化（把对角写在负实部）属于实现契约。</p><p><span class="marginnote">初学者容易以为「选择」是模型在挑「看哪些过去的 token」——那是注意力。这里过去已被压缩进固定维的 \\(h\\)，选择挑的是「此刻往摘要里写什么、忘什么」。所以精确背出第 3000 个 token 仍受 \\(N\\) 限制：摘要再聪明，也装不下全文。</span></p><p><span class="marginnote">\\(N\\) 与 \\(d_{\\mathrm{model}}\\) 的关系后课「状态大小对上下文」再定量。本课只需要：选择不能凭空增加状态维，它只改善怎么用已有维。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>扫描按定义是串行的，朴素实现喂不饱 GPU——下一课的主题。无卷积意味着不能用 S4 那套 FFT 当训练主核。精确逐 token 召回仍受 \\(N\\) 限制，线性召回瓶颈课会用基准说明。不要在已经写成卷积的 S4 检查点上只把 \\(B\\) 改成依赖 \\(x\\) 却仍调 FFT，那条路在数学上已经断了。</p>',8)),(l(),i(B,null,{default:t(()=>[s(r,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20Xt%5B%22x_t%22%5D%20--%3E%20Proj%5B%22%E6%8A%95%E5%BD%B1%E5%BE%97%E5%88%B0%20Delta%20B%20C%22%5D%0A%20%20Proj%20--%3E%20Disc%5B%22%E7%A6%BB%E6%95%A3%E5%8C%96%20A_bar%20B_bar%22%5D%0A%20%20Ht%5B%22h_%7Bt-1%7D%22%5D%20--%3E%20Up%5B%22h_t%20%3D%20A_bar%20h%20%2B%20B_bar%20x%22%5D%0A%20%20Disc%20--%3E%20Up%0A%20%20Up%20--%3E%20Yt%5B%22y_t%20%3D%20C_t%20h_t%22%5D%0A%20%20Up%20--%3E%20Next%5B%22%E4%BC%A0%E5%85%A5%20t%2B1%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e("h2",{id:"小结",tabindex:"-1"},[n("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=e("ul",null,[e("li",null,"选择性扫描让 \\(\\Delta,B,C\\) 随 token 变，卷积核不再存在，改用沿长度的状态扫描。"),e("li",null,"\\(\\Delta\\) 控制写与忘，\\(B,C\\) 控制写进哪维、读出哪维；过去在 \\(h\\) 里而不是 KV 表里。"),e("li",null,"\\(A\\) 保持结构化衰减，以稳住线性 RNN 的谱。"),e("li",null,"代数结合律留给分块并行；朴素扫描的硬件问题留给下一课。"),e("li",null,"出处：Gu & Dao, 2023。")],-1))])}const b=p(A,[["render",d]]);export{x as __pageData,b as default};
